"""Diffusion lesson: photo-like stages and explicit training/conditioning paths."""
from common import *
from itertools import count

_clip_ids = count()


def cat_panel(index, x, y, w=136, h=180):
    # Crop only the SVG display window; preserve the original bitmap.
    clip = f'diffusion-cat-clip-{next(_clip_ids)}'
    scale = max(w / 422, h / 714)
    image_x = x - (index * 434.4 + 6) * scale + (w - 422 * scale) / 2
    image_y = y - 5 * scale + (h - 714 * scale) / 2
    return (f'<defs><clipPath id="{clip}"><rect x="{x}" y="{y}" width="{w}" height="{h}"/></clipPath></defs>'
            f'<image href="assets/diffusion-cat-stages.png" x="{image_x}" y="{image_y}" width="{2172 * scale}" height="{724 * scale}" clip-path="url(#{clip})"/>')



def stages(reverse=False):
    order = range(5) if reverse else range(4, -1, -1)
    labels = ['xT ∼ N(0, I)', '大きな形が現れる', '猫の輪郭が現れる', '毛並みが整う', '生成画像'] if reverse else ['画像 x₀', '少しノイズ', 'さらにノイズ', 'ほぼノイズ', '時刻 T']
    b = ''
    for i, panel in enumerate(order):
        x = 12 + i * 158
        b += txt(x + 68, 26, labels[i], 14) + cat_panel(panel, x, 44)
        if i < 4:
            b += line(x + 139, 133, x + 154, 133)
    b += txt(400, 255, 't を減らす → 同じ予測器で予測し、サンプラで更新' if reverse else 't を増やす → 元画像の信号が弱まり、ノイズが強くなる', 15)
    caption = '写真風の猫で段階を表したAI生成の説明図。実際のDDPMの中間出力や、式を数値計算した画像ではありません。'
    if reverse:
        caption += '生成は新しいノイズから始めます。上の元画像を保存して逆再生する処理ではありません。'
    return figure(svg(b, 280, label='ノイズから徐々に猫が現れる' if reverse else '猫の画像が徐々にノイズへ崩れる'), caption)


def training():
    b = cat_panel(4, 20, 50, 105, 135) + txt(72, 30, '訓練画像 x₀', 15)
    b += box(165, 85, 150, 65, '既知の式で混ぜる', 'xₜ を作る') + line(130, 116, 157, 116)
    b += box(165, 205, 150, 65, 'ランダムな ε', '正解として保存', BLUE) + line(240, 200, 240, 155)
    b += box(345, 85, 170, 65, '予測器 εθ(xₜ,t)', 'U-Net / Transformer') + line(320, 116, 338, 116)
    b += box(345, 5, 170, 55, '時刻 t', '例：1〜Tから選ぶ', BLUE) + line(430, 63, 430, 80)
    b += box(570, 85, 205, 65, '予測したノイズ ε̂', '画像と同じ形の数値', ORANGE) + line(520, 116, 565, 116)
    b += box(570, 205, 205, 65, 'ε と ε̂ の二乗誤差', '逆伝播で θ を更新', ORANGE)
    b += line(672, 155, 672, 200) + line(320, 237, 565, 237)
    b += txt(440, 224, '加えた ε が正解', 13, BLUE)
    b += line(670, 275, 670, 315, ORANGE, arrow=False) + line(670, 315, 550, 315, ORANGE, arrow=False) + line(550, 315, 550, 165, ORANGE, dash=True, arrow=False) + line(550, 165, 430, 165, ORANGE, dash=True, arrow=False) + line(430, 165, 430, 155, ORANGE, dash=True)
    return figure(svg(b, 340, label='訓練画像に加えたノイズを保存し、予測との差から重みを更新する'), '青：学習例を作る入力。橙の点線：損失から予測器へ戻す勾配。x₀や正解εを、答えとして予測器へ渡すことはしません。猫は説明用のAI生成画像。')


def unet():
    b = txt(400, 25, 'U-Netの内部：解像度を下げ、上げながら特徴を合わせる', 18)
    for x, y, title, detail in [(20,70,'高解像度の特徴','畳み込み・輪郭など'), (175,180,'低解像度の特徴','縮小して広く見る'), (325,285,'最も粗い特徴','全体の配置を扱う'), (475,180,'特徴を統合','拡大＋結合'), (630,70,'細部を統合','拡大＋結合')]:
        b += box(x,y,145,70,title,detail)
    b += line(92,145,247,173) + line(247,255,397,278) + line(397,280,547,255) + line(547,175,702,145)
    b += line(169,95,623,95,BLUE,dash=True) + txt(395,81,'同じ解像度の特徴を渡すスキップ接続',13,BLUE)
    b += line(324,215,468,215,BLUE,dash=True) + txt(399,203,'スキップ接続',12,BLUE)
    b += txt(92,58,'入力 xₜ から',14) + txt(702,58,'最後の畳み込み → ε̂',14)
    b += box(25,300,245,65,'時刻 t → 埋め込み','各ブロックの特徴を調整',PURPLE)
    b += txt(400,402,'縮小・拡大は、この1回の予測の内部。拡散の時刻 t を進める操作とは別。',14)
    return figure(svg(b,425,label='U-Netの縮小・拡大と二つのスキップ接続'), '模式図。スキップ接続はノイズ付き入力から抽出した特徴を渡します。学習時のきれいな正解画像を生成時に渡す経路ではありません。')


def transformer():
    b = box(15,45,155,75,'画像・潜在 xₜ','小さなパッチへ',BLUE) + box(210,45,160,75,'パッチの埋め込み','＋位置情報')
    b += box(410,45,175,75,'Transformer × L','Attention ＋ FFN') + box(630,45,155,75,'線形変換・並べ直し','ノイズ予測 ε̂',ORANGE)
    b += line(175,82,204,82)+line(375,82,404,82)+line(590,82,624,82)
    b += box(385,175,230,65,'時刻 t ＋ クラス条件 c','埋め込みで正規化などを調整',PURPLE)+line(500,170,500,127,PURPLE)
    b += txt(185,178,'Attention：離れたパッチと情報交換',13)+txt(185,208,'FFN：各パッチの特徴を変換',13)
    b += txt(400,278,'各パッチの出力を元の位置へ戻し、xₜ と同じ空間形状にする',15)
    return figure(svg(b,305,label='DiTのパッチ化、Transformer、ノイズの出力と時刻・条件の入力'), '代表例としてクラス条件付きDiTの考え方を簡略化。図はノイズ予測の経路に絞り、原論文の分散予測の出力は省略しています。')


def conditioning():
    b = box(20,25,245,65,'文章「座っている茶トラ猫」','画像に対応したキャプション',BLUE)
    b += box(315,25,205,65,'テキストencoder','語をベクトル列へ') + box(570,25,205,65,'条件の表現 c','各語の意味を渡す',PURPLE)
    b += line(270,57,309,57)+line(525,57,564,57)
    b += box(20,175,220,70,'ノイズ付き画像 xₜ ＋ t','画像側の特徴を作る',BLUE)
    b += box(310,175,230,70,'予測器のcross-attention','画像の Q と文章の K・V') + box(590,175,185,70,'条件に応じた ε̂','次の更新に使う',ORANGE)
    b += line(245,210,304,210)+line(545,210,584,210)
    b += line(670,96,670,132,PURPLE,arrow=False)+line(670,132,425,132,PURPLE,arrow=False)+line(425,132,425,170,PURPLE)
    return figure(svg(b,275,label='文章をencoderで表現し、cross-attentionでノイズ予測へ渡す'), '文章条件を使うLDM型の例。Qは画像の特徴、K・Vは文章の特徴から作ります。画像の各位置が、条件文のどの語を参照するかを学びます。')


def build():
    body = sec('why','なぜDiffusionが作られたのか',p('単純なノイズから複雑な画像を一度に作るのは難しい問題です。拡散モデルは、データを少しずつノイズへ崩す過程を用意し、それに対応する逆向きの変化を学びます。DDPMでは、各ノイズ段階で「どんなノイズが混ざっているか」を予測する学習から、段階的な画像生成につなげます。'))
    body += sec('forward','まず、データをノイズへ崩す',p('ここではDDPMのノイズ予測を例にします。時刻tが大きいほど元の信号が少なくなるよう、ノイズの強さを決めます。') + stages() + eq(r'x_t = \sqrt{\bar\alpha_t}\,x_0 + \sqrt{1-\bar\alpha_t}\,\varepsilon,\quad \varepsilon\sim\mathcal N(0,I)', 'x₀は元画像、εは画像と同じ形のランダムな数値です。ᾱₜは元画像の信号をどれだけ残すかを決める係数。例えばᾱₜ=0.64なら、xₜ=0.8x₀+0.6εです。N(0,I)は各成分が独立な平均0・分散1の正規分布を表します。') + p('このノイズ付加には学習は必要ありません。式とスケジュールが分かれば、x₀から好きな時刻tのxₜを直接作れます。学ぶのは、ノイズ付きの画像を見て逆向きの更新に必要な量を予測する部分です。'))
    body += sec('training','学習では、一つの時刻を選んで予測する', p('<strong>正解のノイズは自分で加えたものなので、分かっています。</strong>訓練画像を選び、時刻tとノイズεをランダムに選びます。式でxₜを作り、予測器にはxₜとtを与えます。') + training() + eq(r'L_{\mathrm{simple}}=\mathbb E_{x_0,t,\varepsilon}\left[\lVert\varepsilon-\varepsilon_\theta(x_t,t)\rVert^2\right]', '予測εθと、実際に加えたεの差を、画素・チャネルごとに二乗して集計します。その損失を小さくする方向へ、逆伝播で重みθを更新します。これはDDPMの代表的な簡略化損失です。') + p('例えば、ある成分に加えたノイズが0.6、予測が0.2なら、その成分の二乗誤差は(0.6−0.2)²=0.16です。画像・時刻・ノイズを変えながら多くの例で繰り返すと、同じ予測器が、ノイズの少ない段階から多い段階まで担当できるようになります。') + p('<strong>通常のこの学習では、生成の全ステップを毎回実行しません。</strong>ミニバッチ内の各画像で時刻を選び、その時刻の予測をまとめて学習します。一方、学習後の生成では予測と更新を何度も繰り返します。') + p('一枚のxₜから、元画像や加えたノイズを常に一意に特定できるわけではありません。予測器は多くの訓練例から画像の構造を学び、入力に応じた予測をします。以下はノイズ予測で説明しますが、元画像x₀や、信号とノイズを組み合わせたvを予測する定式化もあります。'))
    body += sec('network','U-NetやTransformerが担う場所', p('<strong>U-NetやTransformerが担当するのは、各時刻の「ノイズの予測」です。</strong>例えばRGB画像なら、入力xₜが64×64×3のとき、予測するノイズも64×64×3です。「猫である確率」を一つ返す分類器ではなく、各位置・各チャネルの数値を出力します。') + flow([('入力 xₜ・t','条件付きなら c も',BLUE),('予測器 εθ','U-Net / Transformer'),('サンプラ','予測を使って更新'),('次の状態 xₜ₋₁','次回の予測の入力',ORANGE)], 'ニューラルネットワークによる予測と、サンプラによる状態の更新を分けて考える。生成中は同じ重みθを繰り返し使う。') + sub('U-Net：全体の配置と細部を合わせる',unet() + p('縮小側では畳み込みで特徴を抽出し、空間の解像度を下げて、広い範囲の配置を捉えます。拡大側では解像度を戻し、同じ解像度の縮小側の特徴をスキップ接続で受け取ります。これにより、全体の形を踏まえながら、輪郭や毛並みのような細かな位置情報を利用できます。') + p('時刻tもベクトルへ変換し、各ブロックに加えたり、特徴のスケールや偏りを調整したりします。同じ猫らしい模様でも、強いノイズの段階と仕上げの段階では必要な予測が違うためです。拡散モデルのU-NetにはAttentionを組み込む設計もあります。')) + sub('Transformer／DiT：パッチ間で情報を交換する',transformer() + p('画像、または圧縮した潜在表現を小さなパッチに区切り、それぞれをベクトルにします。位置情報を加え、Self-Attentionで離れたパッチの関係を、FFNで各パッチの特徴を処理します。最後にパッチごとの予測を空間上に並べ直します。') + p('原論文のDiTでは、時刻とクラスの埋め込みから正規化の係数などを調整する方式（adaLN）を使います。文章を扱うモデルではcross-attentionなどの設計もあります。U-Netの縮小・拡大の段数やTransformerの層数は「1回の予測の深さ」、拡散ステップ数は「その予測器を呼ぶ回数」です。')))
    body += sec('conditional','条件付き生成：何を作るかも入力する',p('無条件生成は、学んだ画像の分布から画像を作ります。条件付き生成では、クラス「猫」、文章「座っている茶トラ猫」、輪郭画像などを条件cとして与え、その条件に合う画像の分布を学びます。同じ条件でも初期ノイズが違えば、異なる画像を作れます。') + conditioning() + p('文章はテキストencoderでベクトル列へ変換します。cross-attentionでは、画像側の各位置が文章中の語を参照し、その情報を画像の特徴へ取り込みます。条件は最後に画像へ貼り付けるものではなく、各段階のノイズ予測に影響します。') + sub('学習時：画像と条件をペアで用意する',p('文章から生成したければ、画像x₀とその内容を説明するキャプションcをペアで用意します。画像へノイズを加え、予測器にはxₜ・t・cを渡します。元のキャプションには通常、画像と同じガウスノイズを加えません。正解は無条件の場合と同じく、自分で加えたεです。') + eq(r'L_{\mathrm{cond}}=\mathbb E_{(x_0,c),t,\varepsilon}\left[\lVert\varepsilon-\varepsilon_\theta(x_t,t,c)\rVert^2\right]', '条件に合う画像でのノイズ予測を繰り返し練習することで、条件の意味と画像の構造を結び付けます。予測器の重みを更新し、テキストencoderを固定するか同時に学習するかは設計によります。')) + sub('生成時：文章を固定して、予測と更新を繰り返す',p('訓練画像x₀は渡さず、新しいノイズxTと条件cを用意します。各時刻で同じcを予測器へ渡し、条件に沿った予測を使って状態を更新します。条件付き生成には、内容の対応した学習データが必要です。文章を入力欄に追加するだけで、未学習の対応を自由に扱えるわけではありません。')) + sub('条件への追従を強める：Classifier-Free Guidance',p('CFGを使うための学習では、一部の例で条件を空の条件∅へ置き換え、同じ予測器に条件あり・条件なしの両方を練習させます。生成時には同じxₜとtで両方を予測し、その差を使います。') + eq(r'\hat\varepsilon=\varepsilon_\theta(x_t,t,\varnothing)+s\left[\varepsilon_\theta(x_t,t,c)-\varepsilon_\theta(x_t,t,\varnothing)\right]', 'この書き方ではs=0が条件なし、s=1が通常の条件付き予測、s>1が条件方向の強調です。合成した予測をサンプラへ渡します。') + p('CFGは別の分類器を使わずに条件への追従を調整する方法です。sを大きくしすぎると、多様性の低下や不自然な画像につながることがあります。条件付き生成そのものとCFGは区別しましょう。')))
    body += sec('sampling','利用時は、予測して一歩戻す操作を繰り返す',stages(True) + p('最初のxTは、画像と同じ形のランダムなノイズです。予測器が返すε̂をそのまま一度引くだけではなく、サンプラが時刻ごとの係数を使ってxₜを更新します。DDPMでは途中の更新に確率的なノイズも加えます。別のサンプラでは更新式やステップ数が変わります。') + p('生成中は重みθを固定し、変わるのは画像の状態xₜと時刻tです。学習済みの予測器を繰り返し使い、最終的な画像を得ます。生成の速さは、解像度、予測器の大きさ、呼び出す回数などで変わります。') + sub('Latent Diffusion：画像を圧縮した空間で行う',flow([('潜在のノイズ zT','生成の出発点',BLUE),('潜在で予測・更新','時刻を減らして反復'),('潜在 z₀','画像の圧縮表現'),('AEのdecoder','画像へ戻す',ORANGE)], '学習時は画像をAEのencoderで潜在へ変換し、その潜在にノイズを加える。新規生成時は潜在のノイズから開始し、最後にdecoderを使う。') + p('ピクセル空間の高解像度計算を減らすため、あらかじめ学んだAEの潜在表現に拡散過程を適用します。この場合、予測するノイズの形状も潜在と同じです。潜在の各成分はRGB画素ではないため、途中の潜在をそのまま猫の写真として見ることはできません。')))
    body += refs([('DDPM：ノイズ予測による学習と生成','https://arxiv.org/abs/2006.11239'),('Latent Diffusion：潜在空間とcross-attention','https://arxiv.org/abs/2112.10752'),('DiT：Transformerを予測器にする','https://arxiv.org/abs/2212.09748'),('Classifier-Free Diffusion Guidance','https://arxiv.org/abs/2207.12598')])
    page('diffusion','Diffusion — ノイズから段階的に生成する','モデルの構造','MODEL 09 / DENOISING DIFFUSION','猫がノイズへ崩れ、ノイズから猫が現れる。予測器の内部、学習の正解、文章による条件付けを順に見ます。',body)
